insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-jonah','sequence',32,1,2,2,'Jonah 1 – Jonah 4',1,'Put these events in order: Jonah and Nineveh',null,'["God calls Jonah to go to Nineveh", "Jonah flees toward Tarshish", "A great fish swallows Jonah", "Jonah warns Nineveh: forty days", "God prepares a gourd to shade Jonah"]'::jsonb,0,'God calls Jonah to go to Nineveh (Jonah 1:2) → Jonah flees toward Tarshish (Jonah 1:3) → A great fish swallows Jonah (Jonah 1:17) → Jonah warns Nineveh: forty days (Jonah 3:4) → God prepares a gourd to shade Jonah (Jonah 4:6)','The first event is in Jonah 1.',null,null,'KJV',array['jonah','Jonah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
