insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-passion','sequence',40,21,9,9,'Matthew 21 – Matthew 28',1,'Put these events in order: The Final Week',null,'["Crowds cry Hosanna as Jesus enters Jerusalem", "Jesus breaks bread at the Last Supper", "Jesus prays in Gethsemane", "Jesus is crucified", "The angel says: He is not here, for he is risen"]'::jsonb,0,'Crowds cry Hosanna as Jesus enters Jerusalem (Matthew 21:9) → Jesus breaks bread at the Last Supper (Matthew 26:26) → Jesus prays in Gethsemane (Matthew 26:36) → Jesus is crucified (Matthew 27:35) → The angel says: He is not here, for he is risen (Matthew 28:6)','The first event is in Matthew 21.',null,null,'KJV',array['passion','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-resurrection','sequence',42,24,2,3,'Luke 24 – Luke 24',3,'Put these events in order: From the Tomb to the Ascension',null,'["The women find the stone rolled away", "Two disciples walk to Emmaus", "Jesus stands among the disciples: Peace be unto you", "Jesus is carried up into heaven"]'::jsonb,0,'The women find the stone rolled away (Luke 24:2-3) → Two disciples walk to Emmaus (Luke 24:13) → Jesus stands among the disciples: Peace be unto you (Luke 24:36) → Jesus is carried up into heaven (Luke 24:51)','The first event is in Luke 24.',null,null,'KJV',array['resurrection','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-church','sequence',44,1,9,9,'Acts 1 – Acts 9',3,'Put these events in order: The Early Church',null,'["Jesus is taken up in a cloud", "The Spirit comes at Pentecost", "A lame man is healed at the temple gate", "Stephen is stoned", "Saul meets the risen Jesus near Damascus"]'::jsonb,0,'Jesus is taken up in a cloud (Acts 1:9) → The Spirit comes at Pentecost (Acts 2:1-4) → A lame man is healed at the temple gate (Acts 3:6-8) → Stephen is stoned (Acts 7:59) → Saul meets the risen Jesus near Damascus (Acts 9:3-4)','The first event is in Acts 1.',null,null,'KJV',array['church','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-paul','sequence',44,9,3,3,'Acts 9 – Acts 28',4,'Put these events in order: Paul''s Journeys',null,'["Saul is converted near Damascus", "Barnabas and Saul are separated for the work", "Paul sees a vision of a man of Macedonia", "Paul preaches on Mars'' hill in Athens", "Paul is shipwrecked on Melita"]'::jsonb,0,'Saul is converted near Damascus (Acts 9:3) → Barnabas and Saul are separated for the work (Acts 13:2) → Paul sees a vision of a man of Macedonia (Acts 16:9) → Paul preaches on Mars'' hill in Athens (Acts 17:22) → Paul is shipwrecked on Melita (Acts 28:1)','The first event is in Acts 9.',null,null,'KJV',array['paul','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-prodigal','sequence',42,15,12,12,'Luke 15 – Luke 15',2,'Put these events in order: The Prodigal Son',null,'["The younger son asks for his portion", "He wastes his substance with riotous living", "He feeds swine in a far country", "His father runs to embrace him", "The elder brother is angry"]'::jsonb,0,'The younger son asks for his portion (Luke 15:12) → He wastes his substance with riotous living (Luke 15:13) → He feeds swine in a far country (Luke 15:15) → His father runs to embrace him (Luke 15:20) → The elder brother is angry (Luke 15:28)','The first event is in Luke 15.',null,null,'KJV',array['prodigal','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification) values ('seq-samaritan','sequence',42,10,30,30,'Luke 10 – Luke 10',1,'Put these events in order: The Good Samaritan',null,'["A traveller falls among thieves", "A priest passes by", "A Levite passes by", "A Samaritan binds up his wounds", "He pays the host two pence"]'::jsonb,0,'A traveller falls among thieves (Luke 10:30) → A priest passes by (Luke 10:31) → A Levite passes by (Luke 10:32) → A Samaritan binds up his wounds (Luke 10:33-34) → He pays the host two pence (Luke 10:35)','The first event is in Luke 10.',null,null,'KJV',array['samaritan','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-14", "human_review": "pending"}'::jsonb) on conflict (id) do nothing;
insert into public.adventures (id, title, summary, testament, image_id, sort_order, status) values ('ot-journey','From Eden to Exile','Walk through the Old Testament: creation, the patriarchs, the exodus, the kingdom and the prophets.','OT','creation',0,'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('ot-1','ot-journey',1,'In the Beginning','Genesis 1–9','Genesis opens with God creating the heavens and the earth (Genesis 1:1). It tells of the first people in Eden, the first sin, and the flood from which Noah, his family and the animals were saved in the ark (Genesis 6–9).','creation',array['pic-creation-1','pic-noah_ark-1','who-noah','who-adam','who-cain','who-enoch']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('ot-2','ot-journey',2,'The Patriarchs','Genesis 12–50','God called Abram to leave his homeland and promised to make of him a great nation (Genesis 12:1-3). The promise passed to Isaac and Jacob, and Joseph''s journey from slavery to leadership brought Jacob''s family to Egypt (Genesis 37–50).','abraham_stars',array['pic-abraham_stars-1','pic-joseph_coat-1','who-abraham','who-jacob','who-joseph','who-esau']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('ot-3','ot-journey',3,'Out of Egypt','Exodus 1–20','Generations later Israel was enslaved in Egypt. God called Moses from the burning bush (Exodus 3), brought the people out through the Red Sea (Exodus 14) and gave the Ten Commandments at Sinai (Exodus 20).','moses_red_sea',array['pic-moses_red_sea-1','who-moses','who-miriam','seq-exodus','seq-plagues','seq-wilderness']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('ot-4','ot-journey',4,'Into the Land','Joshua – Ruth','Under Joshua, Israel crossed the Jordan and entered Canaan (Joshua 3–6). In the time of the judges, leaders such as Deborah, Gideon and Samson rose up, and the book of Ruth shows faithfulness in a difficult age.','moses_red_sea',array['who-joshua','who-rahab','who-gideon','who-samson','who-deborah','who-ruth']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('ot-5','ot-journey',5,'The Kingdom','1 Samuel – 1 Kings 11','Samuel anointed Saul and then David as king (1 Samuel 10; 16). David defeated Goliath and later reigned in Jerusalem; his son Solomon built the temple (1 Kings 6–8).','david_goliath',array['pic-david_goliath-1','pic-solomon_temple-1','who-samuel','who-saul','who-david','who-solomon']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('ot-6','ot-journey',6,'Prophets and Exile','1 Kings 17 – Malachi','Prophets such as Elijah, Isaiah and Jeremiah called the people back to God. Judah went into exile in Babylon, where Daniel served; Esther''s courage protected her people, and Nehemiah later rebuilt Jerusalem''s walls.','daniel_lions',array['pic-elijah_carmel-1','pic-daniel_lions-1','pic-esther_king-1','pic-jonah_fish-1','who-elijah','who-elisha']::text[],'review') on conflict (id) do nothing;
insert into public.adventures (id, title, summary, testament, image_id, sort_order, status) values ('nt-journey','The Way of the Gospel','Follow the life and teaching of Jesus, the birth of the church and the journeys that carried the message outward.','NT','sermon_mount',1,'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('nt-1','nt-journey',1,'The Promised Child','Matthew 1–2; Luke 1–2','The angel Gabriel was sent to Mary in Nazareth (Luke 1:26-31). Jesus was born in Bethlehem and laid in a manger (Luke 2:7), and wise men came with gifts (Matthew 2:11).','nativity',array['pic-nativity-1','who-mary','who-john_baptist','pic-nativity-2','pic-nativity-3','pic-nativity-4']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('nt-2','nt-journey',2,'Teacher of Galilee','Matthew 4–7; Mark 4','Jesus called fishermen to follow Him (Matthew 4:19), taught the Sermon on the Mount (Matthew 5–7) and calmed the storm on the sea of Galilee (Mark 4:39).','sermon_mount',array['pic-sermon_mount-1','pic-calming_storm-1','seq-ministry','who-peter','who-matthew','who-zacchaeus']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('nt-3','nt-journey',3,'Parables of the Kingdom','Luke 10; 15','Jesus often taught in parables. The Good Samaritan answers the question "Who is my neighbour?" (Luke 10:29-37), and the Prodigal Son pictures a father''s welcome for a returning child (Luke 15:11-32).','good_samaritan',array['pic-good_samaritan-1','pic-prodigal_son-1','seq-prodigal','seq-samaritan','who-martha','pic-good_samaritan-2']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('nt-4','nt-journey',4,'Cross and Empty Tomb','Matthew 21–28; John 11; 20','Jesus entered Jerusalem to cries of "Hosanna" (Matthew 21:9), shared the Last Supper, was crucified, and on the first day of the week the tomb was found empty (Mark 16:2-6).','empty_tomb',array['pic-empty_tomb-1','seq-passion','seq-resurrection','who-lazarus','who-judas','who-mary_magdalene']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('nt-5','nt-journey',5,'The Church Is Born','Acts 1–9','At Pentecost the Holy Spirit came upon the believers and Peter preached to the crowds (Acts 2). Stephen was martyred, and Saul of Tarsus met the risen Jesus on the road to Damascus (Acts 7–9).','pentecost',array['pic-pentecost-1','seq-church','who-stephen','who-barnabas','who-paul','pic-pentecost-2']::text[],'review') on conflict (id) do nothing;
insert into public.adventure_chapters (id, adventure_id, position, title, reference_label, narrative, image_id, question_ids, status) values ('nt-6','nt-journey',6,'To the Ends of the Earth','Acts 13 – Revelation','Paul carried the message across the Roman world and wrote letters to the churches. Acts ends with Paul in Rome (Acts 28), and the Bible closes with John''s vision of a new heaven and a new earth (Revelation 21).','paul_ship',array['pic-paul_ship-1','who-lydia','who-timothy','who-john_apostle','scr-cv-revelation-3-20','scr-cv-philippians-4-6']::text[],'review') on conflict (id) do nothing;
